    n = int(n or 0)
    if unit == 'calendar_days':
        return d + datetime.timedelta(days=(n - 1 if counts_today else n))
    if counts_today and is_bd(d):
        n -= 1
        if n <= 0:
            return d
    x = d
    for _ in range(n):
        x = next_bd(x)
    return x
